using System.Numerics;

namespace Asteria.Core.World;

/// <summary>
/// Lightweight, engine-independent visual chips generated by validated
/// mining feedback. No block mutations, collision, damage or loot.
/// </summary>
public sealed class MiningParticleRuntime
{
    public const int MaximumActive = 96;
    private const float MaximumDelta = 0.05f;
    private readonly List<MiningParticle> _particles = new(MaximumActive);
    private uint _random = 0x9E3779B9;

    public IReadOnlyList<MiningParticle> Particles => _particles;

    public void Emit(MiningFeedbackEvent feedback,
        Vector3? authoredTint = null)
    {
        var hit = feedback.Hit;
        var normal = new Vector3(hit.NormalX, hit.NormalY, hit.NormalZ);
        if (normal.LengthSquared() < 0.5f)
            normal = Vector3.UnitY;
        var position = new Vector3(
            hit.Voxel.X + 0.5f, hit.Voxel.Y + 0.5f, hit.Voxel.Z + 0.5f)
            + normal * 0.515f;
        var count = feedback.Completed ? 11 : 3;
        for (var i = 0; i < count && _particles.Count < MaximumActive; ++i)
        {
            var jitter = new Vector3(Signed(), Signed(), Signed()) * 0.28f;
            // Distribute fragments over the *hit face*, never bury them in
            // the still-solid block.
            jitter -= normal * Vector3.Dot(jitter, normal);
            var speed = feedback.Completed ? 1.35f : 0.65f;
            var velocity = normal * (0.35f + Unit() * speed) +
                new Vector3(Signed(), Unit(), Signed()) * 0.72f;
            var size = 0.032f + Unit() * 0.046f;
            var lifetime = (feedback.Completed ? 0.36f : 0.23f) +
                Unit() * 0.18f;
            _particles.Add(new MiningParticle(position + jitter,
                velocity, size, lifetime, feedback.Appearance,
                authoredTint ?? Vector3.One));
        }
    }

    public void Advance(float elapsedSeconds)
    {
        if (!float.IsFinite(elapsedSeconds) || elapsedSeconds < 0f)
            throw new ArgumentOutOfRangeException(nameof(elapsedSeconds));
        var dt = MathF.Min(elapsedSeconds, MaximumDelta);
        for (var i = _particles.Count - 1; i >= 0; --i)
        {
            var particle = _particles[i];
            particle.Age += dt;
            if (particle.Age >= particle.Lifetime)
            {
                _particles.RemoveAt(i);
                continue;
            }
            var velocity = particle.Velocity;
            velocity.Y -= 7.5f * dt;
            particle.Position += velocity * dt;
            particle.Velocity = velocity;
        }
    }

    public void Clear() => _particles.Clear();

    private float Unit()
    {
        _random ^= _random << 13;
        _random ^= _random >> 17;
        _random ^= _random << 5;
        return (_random >> 8) * (1f / 16777216f);
    }

    private float Signed() => Unit() * 2f - 1f;
}

public sealed class MiningParticle
{
    internal MiningParticle(Vector3 position, Vector3 velocity,
        float size, float lifetime,
        MiningFragmentAppearance? appearance, Vector3 tint)
    {
        Position = position;
        Velocity = velocity;
        Size = size;
        Lifetime = lifetime;
        Appearance = appearance;
        Tint = tint;
    }

    public MiningFragmentAppearance? Appearance { get; }
    public Vector3 Tint { get; }
    public Vector3 Position { get; internal set; }
    internal Vector3 Velocity { get; set; }
    internal float Age { get; set; }
    internal float Lifetime { get; }
    internal float Size { get; }
    public float Scale => Size * (1f - Age / Lifetime);
}
